library(readr) library(dplyr) input_dir <- "C:/Users/isuji/Desktop/Ph.D/Research/Osimertinib/NONMEM/VER5.6/SIM/INTER/PRED/RESULT/STEP2/P" output_dir <- "C:/Users/isuji/Desktop/Ph.D/Research/Osimertinib/NONMEM/VER5.6/SIM/INTER/PRED/RESULT/STEP3/P" #input_dir <- "C:/Users/isuji/Desktop/Ph.D/Research/Osimertinib/NONMEM/VER5.6/SIM/TEST/RESULT/STEP2/M" #output_dir <- "C:/Users/isuji/Desktop/Ph.D/Research/Osimertinib/NONMEM/VER5.6/SIM/TEST/RESULT/STEP3/M" # 오타 수정 if (!dir.exists(output_dir)) dir.create(output_dir, recursive = TRUE) for (k in 1000:1539) { in_file <- file.path(input_dir, sprintf("SIM%d_P.csv", k)) out_file <- file.path(output_dir, sprintf("SIM%d_P.csv", k)) if (!file.exists(in_file)) { message("파일 없음: ", in_file); next } df <- read_csv(in_file, show_col_types = FALSE) need_cols <- c("ID","TIME","AMT","ADDL","II","CMT","WT","ALB","AST","SEX","PRED") if (!all(need_cols %in% names(df))) stop(sprintf("필수 컬럼 누락: %s", in_file)) # ID==1의 TIME별 공통 변수 ref_tbl <- df %>% filter(ID == 1) %>% select(TIME, AMT, ADDL, II, CMT, WT, ALB, AST, SEX,PRED) %>% group_by(TIME) %>% slice(1) %>% ungroup() # (옵션) ID==1의 '상수' 기본값: TIME 누락 시 대체용 ref_const <- df %>% filter(ID == 1) %>% select(AMT, ADDL, II, CMT, WT, ALB,AST, SEX, PRED) %>% slice(1) if (nrow(ref_const) == 0) stop(sprintf("ID==1 행이 없습니다: %s", in_file)) # TIME별 median(PRED) med_tbl <- df %>% group_by(TIME) %>% summarise(PRED = median(PRED, na.rm = TRUE), .groups = "drop") %>% arrange(TIME) # 조인 후, ID==1의 해당 TIME이 없어서 NA가 생기면 ref_const로 보정 out <- med_tbl %>% left_join(ref_tbl, by = "TIME") %>% mutate(ID = k) %>% mutate( AMT = ifelse(is.na(AMT), ref_const$AMT[1], AMT), ADDL = ifelse(is.na(ADDL), ref_const$ADDL[1], ADDL), II = ifelse(is.na(II), ref_const$II[1], II), CMT = ifelse(is.na(CMT), ref_const$CMT[1], CMT), WT = ifelse(is.na(WT), ref_const$WT[1], WT), ALB = ifelse(is.na(ALB), ref_const$ALB[1], ALB), AST = ifelse(is.na(AST), ref_const$AST[1], AST), # AGE -> AST 수정 SEX = ifelse(is.na(SEX), ref_const$SEX[1], SEX), # 쉼표 추가 PRED = ifelse(is.na(PRED.y), ref_const$PRED[1], PRED.y) # PRED.y 수정 및 참조 수정 ) %>% select(ID, TIME, AMT, ADDL, II, CMT, WT, ALB, AST, SEX, PRED) write_csv(out, out_file) } cat("처리 완료 → ", output_dir, "\n")